local utils = require(script.Parent)

local module = {}
module.__index = module

function module.new(serviceProvider: IServiceProvider)
	local self = setmetatable({}, module)
	self.serviceProvider = serviceProvider
	return self
end

function module:CreateInstance(targetType: string | ModuleScript, ...)
	return utils.CreateInstance(self.serviceProvider, targetType, ...)
end

return module
